import{_ as i,a0 as e,w as l,s as u,I as o,x as n,a1 as r,A as s,ao as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"技術視點：李納斯·託沃茲，Linux的締造者 | LCTT x X-CMD","titleTemplate":false,"description":"技術視點：李納斯·託沃茲，Linux的締造者 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"技術視點：李納斯·託沃茲，Linux的締造者 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"技術視點：李納斯·託沃茲，Linux的締造者 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/TechView--Linus Torvalds Inventor of Linux","title":"技術視點：李納斯·託沃茲，Linux的締造者","tag":"201406","desc":""},"relativePath":"201406/TechView--Linus Torvalds Inventor of Linux.md","filePath":"[post].md"}'),a={name:"201406/TechView--Linus Torvalds Inventor of Linux.md"};function T(d,t,L,x,m,f){const p=e("Link");return l(),u("div",null,[t[15]||(t[15]=o("h1",{id:"技術視點-李納斯·託沃茲-linux的締造者",tabindex:"-1"},[n("技術視點：李納斯·託沃茲，Linux的締造者 "),o("a",{class:"header-anchor",href:"#技術視點-李納斯·託沃茲-linux的締造者","aria-label":"Permalink to “技術視點：李納斯·託沃茲，Linux的締造者”"},"​")],-1)),t[16]||(t[16]=o("p",null,[o("img",{src:"http://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Linus_Torvalds%2C_2002%2C_Australian_Linux_conference.jpg/800px-Linus_Torvalds%2C_2002%2C_Australian_Linux_conference.jpg",alt:""})],-1)),o("blockquote",null,[o("p",null,[t[1]||(t[1]=n("我們的第一個談話對象是",-1)),r(p,{href:"http://en.wikipedia.org/wiki/Linus_Torvalds"},{default:s(()=>[...t[0]||(t[0]=[n("李納斯·託沃茲",-1)])]),_:1}),t[2]||(t[2]=n("，Linux的傳奇締造者以及開源革命的先驅。託沃茲生於芬蘭的赫爾辛基，是詩人奧爾·託沃茲的孫子。儘管他更喜歡告訴人們，他的名字來自於《花生漫畫》中的角色，但事實是他是以李納斯·鮑林——一位兩次諾貝爾獎獲得者的名字來命名的。他的計算機經歷是從一台Commodore計算機上開始的，後來換成了Sinclair和IBM的386。他起初使用的是Minix操作系統，後來換成了他自己的Linux操作系統。託沃茲的妻子託芙是六次芬蘭全國空手道冠軍，婚後他們定居在加利佛尼亞的聖何塞，育有三個女兒。",-1))])]),t[17]||(t[17]=g("<p><strong>技術視點（TV）</strong>：在當今的技術中，有什麼令你感興趣？</p><p><strong>託沃茲</strong>：我差不多是個“鼠目寸光”的傢伙，所以相對於那些更空洞的“大潮流”，我對實實在在的技術創新更感興趣。</p><p>我很關注硬件廠商的新產品和最新的芯片，而最能吸引我的（因為畢竟我是個做軟件的）是那些開發出新的算法和軟件來充分利用這些新功能的人。</p><p><strong>TV</strong>：那在當今科技中，什麼會讓你感到惱火？它是怎麼以及為什麼讓你憤怒？</p><p><strong>託沃茲</strong>：我不會用“憤怒”這個詞，但是如果真要説技術領域中有什麼讓人反感的，那無疑是對那些頭頂光環的“領袖”們的讚美。</p><p>是的，這種情況也發生在我身上。但是我很不喜歡人們把我以及我所説的話太當回事。我認為，現在流行的“個人崇拜”相當令人不安，即使是對於喬布斯，埃裏森，蓋茨等眾所周知的領袖來説，這個現象也不正常。我希望更多的人能有自主思考，並能意識到技術發展實際上來源於遍佈全球的那些默默無聞的偉大工程師的共同智慧。</p><p>我理解人們渴望明星，而這種事也不僅僅發生在技術世界中（嘿，我的確希望這事在技術世界中要比娛樂行業來得少 😉 ），但是，這還是有點令人沮喪。</p><p><strong>TV</strong>：相比Red Hat和SuSE,你為什麼沒有抓住商業授權的機遇？難道如果Linux不開源，它就不會成為Linux了嗎？你能談談更多情況嗎？你是否曾在此事上感到過後悔？</p><p><strong>託沃茲</strong>：我肯定不會因為任何事情自責。我現在身在一個令人羨慕的位置上，我能幹我喜歡的事情，並贏得大家的尊重。況且，以前一文不得的時候我就很享受我的工作，而現在我從工作中得到了不錯的報酬</p><p>我相信，很少有人能有機會做與眾不同的事情，讓我來告訴你吧，這種感覺真不錯。對於商業，我從來都不感興趣。對我來説，那些把Linux商業化的人替我做了我從沒有動力做的事情。而這項工作的確需要人做，也很有益。因此，事實上我很感謝那些商業機構，它們讓我能集中精力幹我想幹的那部分事情。</p><p><strong>TV</strong>：在當今的科技界，你尊敬的人有哪些？為什麼？</p><p><strong>託沃茲</strong>：哈！這個問題又繞回了我對於“個人崇拜”的看法，對“讓我們找個人並把他神化”這種事，我一點興趣都沒有。</p><p>所以，相比列出來個人名單，我更尊敬像EFF這樣的組織，甚至有時候只是觀念和想法。因為它們不是要單純獲取自身利益，而是努力去做一些實質性的事情來讓技術在一個更大的藍圖中更好地發揮作用。</p><p>在個人層面上，我更喜歡那些不自驕自傲，同時又在他們的本職工作上乾得很好的人。如果一定要我説一些知名人士，我想我更願意成為斯蒂芬·沃茲尼克那樣的人，我想這也是我尊敬他的原因。</p><p><strong>TV</strong>：就谷歌和微軟而言，你認為哪個更成功？為什麼？</p><p><strong>託沃茲</strong>：我認為，相對勝利者來説，兩家公司競爭的過程才是更有趣的。</p><p>在谷歌和微軟的競爭中，我真的不認為兩家公司本身比技術的變革更為有趣。這種變革的本質是從對單個計算機的控制轉向對成千上萬獨立計算機的整合。</p><p><strong>TV</strong>：你認為像科技災難、互聯網泡沫崩潰以及電信業崩盤這樣的事為什麼會發生？我們在今後怎樣來防止它們再發生？</p><p><strong>託沃茲</strong>：實際上，我對此類事情持相反的看法，而且我認為沒有必要去防止它們再次發生。</p><p>我堅信我們應該努力去挑戰極限，而不是追求百分之百的穩定和理性 大多數技術發展都不是有規律可循的，有的像火山爆發，有的事後可能被認為是誇大其詞，有的剛出來時一點都不討人喜歡。但事實上，如果太過努力去保持理性和避免做蠢事，就會扼殺創造力。</p><p>我個人認為，真正穩定可靠的發展模式不是持續的微創新，而是通過超載和崩潰帶來的系統演替。持續的微創新雖然看起來是一個好的選擇，但是不經歷超載和崩潰，你怎麼可能發現系統的極限，並對它進行改進呢？</p><p><strong>TV</strong>：技術在未來會怎樣改變我們的生活？你會和其它領域的領軍者一起創建新技術嗎，比如生物信息學？</p><p><strong>託沃茲</strong>：我個人的理論是，技術對我們的生活的改變，遠沒有我們構建技術來適應我們的生活來得多。</p><p>這就是為什麼你看不到飛行汽車等科幻小説中受歡迎的東西——但是相反，你卻看到了利用技術來降低成本，使得一些此前就存在但是卻因為成本因素不能大規模應用或者量身定製的事情被更多人接受。 因此，技術很少直接改變我們的生活本身——雖然它往往意味着更多的人能獲得那些以前罕見的或只限於土豪們的東西。</p><p>真正的改變發生在當某些事物變得如此廉價並且隨手可得，從而改變了你的行為的時候。而在很多方面，這些行為上的改變要比技術本身來得更有趣。</p><p>例如，互聯網帶來的一大革命，是讓你可以用極低的成本找到志趣相投的人並與他們進行交流。而且，我認為許多真正的改變正是來自於當人們無需付出太多努力就能找到其他對同一事物有相同興趣的人時，他們的習慣會如何改變。</p><p>因此，你發現了所有的這些專業興趣小組，許多人都在花大量時間討論那些最神秘的問題，他們剛剛發現這些問題很有趣——這些事，你在之前不一定能實際去做，因為那時真的很難找到和你一樣在某些不同尋常的專業上感興趣的人並進行討論。</p><p>而我認為那是生活真正改變的方式——不是因為任何新技術的出色特性，而完全是因為技術降低邊際成本後帶來的驚喜。</p><p><strong>TV</strong>：就你而言，誰是當今科技界最舉足輕重的人物？</p><p><strong>託沃茲</strong>：我想大量的技術由消費市場推動，而不再是由軍方或商業需求推動這一點很説明問題。我也常常認為，許多公司正在推進的愚蠢事情（特別是DRM）都忽略了一個事實：任何技術上最重要的人，最終總是“用户”。</p><p>因此，就我而言，我認為你的問題的答案是“用户”，或者叫“消費者”，而這確實是最重要的部分，因為用户正是市場需求和商業成功的根源。</p><p><strong>TV</strong>：請談一些你個人的觀點吧，比如宗教？政治？</p><p><strong>託沃茲</strong>：我完全是一個虔誠的——無神論者。我發現人們似乎認為宗教帶給人道德和對自然的敬畏，但事實上我認為它反而把這兩方面都削弱了。它給了人們藉口説“哇，世界是被創造出來的”，而創世是神秘而不可測的。我更欣賞的説法是“哇，真讓人難以置信，這樣的事情竟然會首先發生”。具有諷刺意味的是，在許多歐洲國家，國家和宗教已經從法律意義上結合在了一起。</p><p>我現在是一位美國公民，並且我也擁有投票權。但是，坦率地説，我不支持任何政黨，因為我的個人驕傲不允許我和任何政黨有關聯。</p><p><strong>TV</strong>：謝謝，李納斯！</p><hr>",36)),o("p",null,[t[4]||(t[4]=n("via: ",-1)),r(p,{href:"http://www.huffingtonpost.com/billrobinson/techview-linus-torvalds-i_b_5338844.html"},{default:s(()=>[...t[3]||(t[3]=[n("http://www.huffingtonpost.com/billrobinson/techview-linus-torvalds-i_b_5338844.html",-1)])]),_:1})]),o("p",null,[t[7]||(t[7]=n("譯者：",-1)),r(p,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[5]||(t[5]=[n("GOLinux",-1)])]),_:1}),t[8]||(t[8]=n(" 校對：",-1)),r(p,{href:"https://github.com/reinoir"},{default:s(()=>[...t[6]||(t[6]=[n("reinoir",-1)])]),_:1}),t[9]||(t[9]=n(",mahua",-1))]),o("p",null,[t[12]||(t[12]=n("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創翻譯，",-1)),r(p,{href:"http://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const w=i(a,[["render",T]]);export{v as __pageData,w as default};
